    var $arrPersonasSubMayorVac = array();

    /**
     * Obtener los datos de vacaciones dado el id persona y entidad.
     *
     * @param int $idpersona Identificador de la persona.
     * @param int $identidad Identificador de la entidad.
     *
     * @return array    Listado de los datos de las vacaciones de una persona.
     */
    public static function obtenerDatosVacacionesPersona ($idpersona, $identidad)
    {
        //Devolviendo los datos de las vacaciones de una persona en forma de arreglo.
        $sql = Doctrine_Query::create()
            ->from('DatVacacionesPersona vac')
            ->where('vac.idpersona = ? and vac.identidad = ?', array($idpersona, $identidad))
            ->orderBy('vac.fechafin')
            ->fetchArray();
        return $sql;
    }

    public static function obtenerDatosVacacionesPersonaEntidad ($identidad)
    {

        //Devolviendo los datos de las vacaciones de una persona en forma de arreglo.
        $sql = Doctrine_Query::create()
            ->from('DatVacacionesPersona vac')
            ->where('vac.identidad = ?', array($identidad))
            ->fetchArray();
        return $sql;
    }


    public static function obtenerSaldoInicialEntidad ($identidad)
    {
        $sqlDatosVac = "select sum(dvac.importeacumuladoinicial) as saldoinicial from mod_nomina.dat_vacacionespersona dvac
		    inner join mod_nomina.conf_vacacionespersona cvp on(cvp.idpersona = dvac.idpersona)
		    inner join mod_nomina.dat_cargosocupados dco on(dco.idpersona = cvp.idpersona)
		    where dco.identidad = ? and cvp.idestructura  = ? and dvac.identidad = ?;";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $arrDatosVac = $conn->fetchAll($sqlDatosVac, array($identidad, $identidad, $identidad));
        return $arrDatosVac;

    }

