    }


    public function obtenerPersonasHanIniciadoSubMayorVac ($identidad, $arrPersonas = null)
    {
        $w = "";
        if($arrPersonas != null){
            $w = "and dv.idpersona in (" . implode(',', $arrPersonas) . ") ";
        }
        $sql = "SELECT DISTINCT (dp.idpersona),dv.idvacacionespersona,dv.tiempoacumuladoinicial, dv.importeacumuladoinicial,nfe.nivel ,cpn.orden,dp.nombre,
                (CASE WHEN dp.snombre is not null THEN dp.snombre ELSE '' END) as snombre,doc.numero as ci,
                (CASE WHEN dp.snombre is not null THEN dp.nombre||' '||dp.snombre||' '||dp.papel||' '||dp.sapel ELSE dp.nombre ||' '||dp.papel||' '||dp.sapel END) as nombrecompleto, 
                (CASE WHEN dcoc.idplantillanominal is not null THEN dcoc.idplantillanominal WHEN cpn.idplantillanominal is not null 
                 THEN cpn.idplantillanominal ELSE -1 END) as idplantillanominal,
                ((CASE WHEN dcoc.idplantillanominal is not null THEN (select cpx.orden ||'-'|| cpx.denominacion
                 from mod_nomina.conf_plantillanominal cpx
                 where cpx.idplantillanominal = dcoc.idplantillanominal) WHEN cpn.denominacion <> ''
                 THEN cpn.orden ||'-'|| cpn.denominacion ELSE 'Sin plantilla nominal' END)) as plantilla

                from mod_nomina.dat_vacacionespersona dv
                inner join mod_persona.dat_persona dp on(dv.idpersona = dp.idpersona)
                inner join mod_nomina.conf_vacacionespersona cvp on(cvp.idpersona = dp.idpersona and cvp.idestructura = " . $identidad . ")
                inner join mod_nomina.dat_cargosocupados dcoc on(dcoc.idpersona = dp.idpersona and dcoc.identidad = " . $identidad . ")
                inner join mod_nomina.conf_plantillanominalcargo cpnca on(cpnca.idcargo = dcoc.idcargo)
                inner join mod_nomina.conf_plantillanominal cpn on(cpn.idplantillanominal = cpnca.idplantillanominal
                and cpn.identidad = " . $identidad . "  and cpn.fechafin is null)
                left join mod_persona.dat_docidentidad doc on(doc.idpersona = dp.idpersona and doc.principal = 1)
                left JOIN mod_estructuracomp.dat_cargo dc on (dc.idcargo = dcoc.idcargo)
                left JOIN mod_estructuracomp.nom_filaestruc nfe on (nfe.idfila = dc.idcargo)
                left JOIN mod_estructuracomp.nom_cargo nc on (nc.idnomcargo = dc.idnomcargo)
                where dv.identidad = " . $identidad . "  {$w}"; //and (dv.fechafin is null or dv.fechafin >= now())
        $sql .= " order by cpn.orden ASC,nfe.nivel ASC  ;";

        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        return $conn->fetchAll($sql);
    }

    public function obtenerIdnominaByIdentidad($identidad)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "SELECT idnomina FROM mod_nomina.dat_nominadatos_json WHERE identidad = ?";
        $result = $conn->fetchAll($sql, array($identidad));
        
        // Extraer solo los valores de idnomina en un array simple
        $idnominas = array();
        foreach ($result as $row) {
            $idnominas[] = (int)$row['idnomina'];
        }
        
        return $idnominas;
    }

