    public function obtenerPersonasAusencias ($identidad, $idpersona, $tiporeporte, $tipovariable, $fechainicio, $fechafin)
    {
        $sql = "select derc.idelemento as idpersona, drc.fechainicio, drc.fechafin, dverc.valor
        from mod_nomina.dat_variableselementosreportescertificaciones dverc
        inner join mod_nomina.dat_elementosreportescertificaciones derc on (derc.idelementosreportescertificaciones = dverc.idelementosreportescertificaciones)
        inner join mod_nomina.dat_reportescertificaciones drc on (drc.idreportescertificaciones = derc.idreportescertificaciones)
        inner join mod_nomina.conf_tiporeportescertificaciones ctrc on (ctrc.idconfreportescertificaciones = drc.idconfreportescertificaciones)
        inner join mod_nomina.conf_variablestiporeportescertificaciones cvtrc on (cvtrc.idconfreportescertificaciones = ctrc.idconfreportescertificaciones and cvtrc.idvariablesconfreportescertificaciones = dverc.idvariablesconfreportescertificaciones)
        where drc.identidad = ? and derc.idelemento = ? and ctrc.deresultados = ? and cvtrc.tipovariable = ? and
       (drc.fechainicio BETWEEN '{$fechainicio}'::date and '{$fechafin}'::date) and (drc.fechafin BETWEEN '{$fechainicio}'::date and '{$fechafin}'::date)";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $arregloElem = $conn->fetchAll($sql, array($identidad, $idpersona, $tiporeporte, $tipovariable));
        return $arregloElem;
    }

    //Optimizar esto
    public function validarExisteCargaInicial ($datosnomina, $identidad)
    {
        $arrpersonassinvacaciones = array();
        $arrpersonassinaddsumbayor = array();
        $contp = 0;
        $conts = 0;
        $ioc = ZendExt_IoC_Inter::getInstance();
        $objconfVacaciones = new ConfVacacionesPersona();
        $objVacacionesPersona = new DatVacacionesPersona();
        foreach($datosnomina as $idn => $rdnn) {
            $valoresn = unserialize($rdnn['valores']);
            //Recorriendo los valores de las personas en las nominas para salvar en el submayor
            foreach($valoresn as $iv => $rvv) {
                $rexplode = explode('-', $rvv['id']);
                $idpersona = $rexplode[0];
                $existepersonasubmayor = $objconfVacaciones->existeVacacionesPersona($idpersona, $identidad);
                if($existepersonasubmayor == 1){
                    $cargainicial = $objVacacionesPersona->obtenerDatosVacacionesPersona($idpersona, $identidad);
                    if(count($cargainicial) == 0){
                        //Datos de la persona
                        $datospersona = $ioc->pvd->getPrincipalesDatosPersona(array($idpersona), null, null, null, null, null);
                        $arrpersonassinvacaciones[$contp] = $datospersona->data[0]['nombre'] . ' ' . $datospersona->data[0]['snombre'] . ' ' . $datospersona->data[0]['sapel'] . ' ' . $datospersona->data[0]['papel'];
                        $contp++;
                    }
                }else{
                    //Datos de la persona
                    $datospersona = $ioc->pvd->getPrincipalesDatosPersona(array($idpersona), null, null, null, null, null);
                    $arrpersonassinaddsumbayor[$idpersona] = $datospersona->data[0]['nombre'] . ' ' . $datospersona->data[0]['snombre'] . ' ' . $datospersona->data[0]['sapel'] . ' ' . $datospersona->data[0]['papel'];
                    $conts++;

                }

            }
        }
        $textonombre = '';
        $codigo = 0;
        /*if (count($arrpersonassinaddsumbayor) > 0) {
            foreach ($arrpersonassinaddsumbayor as $i => $rp) {
                if ($textonombre == '') {
                    $textonombre = $rp;
                } else {
                    $textonombre = $textonombre . ',' . $rp;
                }
            }
            $codigo = 1;
        } else*/
        if(count($arrpersonassinvacaciones)){
            foreach($arrpersonassinvacaciones as $i => $rp) {
                if($textonombre == ''){
                    $textonombre = $rp;
                }else{
                    $textonombre = $textonombre . ',' . $rp;
                }
            }
            $codigo = 2;
        }

        $return->arrpersonassinaddsumbayor = $arrpersonassinaddsumbayor;
        $return->arrpersonassinvacacione = $arrpersonassinvacaciones;
        $return->textonombre = $textonombre;
        $return->codigo = $codigo;
        return $return;
    }

    /*
	 * Devuelve las personas que van a nomina y que estan iniciadas en el submayor de vacaciones
	 * */
    public function obtenerPersonasSubMayorVacaciones ($identidad, $arrPerVanAlaNomina)
    {
        $objVac = new DatVacacionesPersona();
        $objHisVacPer = new HisVacacionesPersona();
        $arrPersonas = null;
        foreach($arrPerVanAlaNomina as $k => $p) {
            $arrPersonas[] = $p['idpersona'];
        }
        if($arrPersonas != null){
            $arrPersonas = array_unique($arrPersonas);
        }

        $r = $objVac->obtenerPersonasHanIniciadoSubMayorVac($identidad, $arrPersonas);
        //print_r($arrPerVanAlaNomina);die;
        foreach($r as $k => $v) {
            foreach($arrPerVanAlaNomina as $j => $p) {
                if($v['idpersona'] == $p['idpersona']){
                    $this->arrPersonasSubMayorVac[$v['idpersona']][$j]->idvacacionespersona = $v['idvacacionespersona'];

                    $arrUltOperacion = $objHisVacPer->obtenerUltimaOperacionSubMayor($v['idvacacionespersona']);
                    if(count($arrUltOperacion) > 0){
                        $saldoentiempo = $arrUltOperacion[0]['saldoentiempo'];
                        $saldoenimporte = $arrUltOperacion[0]['saldoenimporte'];
                    }else{
                        $saldoentiempo = $v['tiempoacumuladoinicial'];
                        $saldoenimporte = $v['importeacumuladoinicial'];
                    }
                    $this->arrPersonasSubMayorVac[$v['idpersona']][$j]->tiempo = $saldoentiempo;
                    $this->arrPersonasSubMayorVac[$v['idpersona']][$j]->importe = $saldoenimporte;
                    if($saldoentiempo > 0){
                        $vac = $saldoenimporte / $saldoentiempo;
                    }else{
                        $vac = 0.00;
                    }
                    $this->arrPersonasSubMayorVac[$v['idpersona']][$j]->promedio = round($vac, 2);

                    $this->arrPersonasSubMayorVac[$v['idpersona']][$j]->idpersona = $v['idpersona'];
                    $this->arrPersonasSubMayorVac[$v['idpersona']][$j]->tiempoacumuladoinicial = $v['tiempoacumuladoinicial'];
                    $this->arrPersonasSubMayorVac[$v['idpersona']][$j]->importeacumuladoinicial = $v['importeacumuladoinicial'];
                    $this->arrPersonasSubMayorVac[$v['idpersona']][$j]->importeacumulado = 0.00;
                    $this->arrPersonasSubMayorVac[$v['idpersona']][$j]->tiempoacumulado = 0.00;
                }
            }
        }
        $arrfinal = $this->arrPersonasSubMayorVac;//print_r($arrfinal);die;
        return $arrfinal;
    }
